        let config = baseline_appeal_pricing_config();
        let request = AppealPricingQuoteRequestDto {
            class: "content".to_owned(),
            backlog: 28,
            evidence_size_mb: 45,
            urgency: Some("normal".to_owned()),
            panel_size: Some(7),
        };
        let input = appeal_quote_input(request, &config).expect("valid quote input");
